window.STORYLAB_ATLAS_GUIDES = [{"scene":"Uma rua com fachada comercial, bancos e árvores","focus":"Formas que organizam a cena: identifique linhas, curvas e padrões sem atribuir estilo arquitetônico sem pesquisa.","terms":[["retilíneo","Que apresenta traçado predominantemente reto.","As linhas retilíneas da fachada contrastam com os galhos das árvores.","Não descreva como retilíneo um contorno com curvas dominantes."],["curvilíneo","Composto por linhas ou superfícies curvas.","O corrimão curvilíneo acompanha a inclinação da escada.","Uma linha levemente inclinada não é necessariamente curva."],["angular","Com quinas e encontros de linhas bem definidos.","A fachada angular alterna planos que se encontram em quinas marcadas.","Não associe automaticamente linhas angulares a um estilo histórico."],["arredondado","Com bordas ou volumes de curvatura suave.","Os bancos arredondados interrompem a sequência de linhas retas.","Arredondado não é necessariamente circular em toda sua extensão."],["simétrico","Com partes correspondentes em torno de um eixo.","As duas janelas criam uma composição quase simétrica em torno da porta.","Observe diferenças antes de afirmar simetria perfeita."],["assimétrico","Sem correspondência de forma ou posição em ambos os lados de um eixo.","A posição assimétrica das janelas destaca a porta lateral.","Assimetria visual não demonstra erro ou falta de planejamento."],["verticalizado","Com predominância da altura e de eixos verticais.","Os painéis verticalizados acentuam a percepção de altura.","Não deduza o número de andares pela orientação da fachada."],["horizontal","Com direção predominante de lado a lado.","Uma marquise horizontal acompanha as vitrines do térreo.","Horizontal não implica ausência de pequenas inclinações."],["modular","Organizado por unidades repetidas ou combináveis.","Os painéis modulares repetem o mesmo desenho na parede.","Repetição visual não prova que os componentes sejam intercambiáveis."],["orgânico","De formas irregulares ou fluidas inspiradas em padrões naturais.","As linhas orgânicas do canteiro suavizam a geometria da calçada.","Orgânico descreve a forma; não prova que o material seja natural."]],"model":["Na cena proposta, duas fachadas apresentam linhas predominantemente retas.","O desenho curvilíneo dos galhos contrasta com a geometria dos edifícios.","Enquanto a fachada se organiza em eixos regulares, a vegetação ocupa o espaço de maneira menos uniforme.","Minha impressão é que essa diferença de formas torna a caminhada visualmente mais variada."],"swaps":[{"vague":"bonito","options":["simétrico","orgânico","modular"],"weak":"A fachada é bonita.","strong":"A fachada é quase simétrica: duas janelas iguais ladeiam a porta central.","flag":true},{"vague":"diferente","options":["assimétrico","curvilíneo","angular"],"weak":"O prédio tem um formato diferente.","strong":"O prédio tem um volume curvilíneo que se destaca entre blocos angulares.","flag":true},{"vague":"estranho","options":["assimétrico","orgânico","angular"],"weak":"O banco tem um design estranho.","strong":"O banco tem contorno orgânico, sem linhas retas, ao contrário dos canteiros.","flag":true}]},{"scene":"Um edifício alto ao lado de pequenas lojas","focus":"Escala e proporção precisam de referências observáveis; altura percebida não é metragem verificada.","terms":[["monumental","De dimensão percebida como muito grande ou imponente em relação ao entorno.","O volume monumental se destaca diante das construções baixas.","Sem medidas, não apresente a altura exata como fato."],["compacto","Com dimensões relativamente contidas e organização concentrada.","O espaço compacto reúne balcão, circulação e vitrines em poucos metros aparentes.","Compacto não equivale necessariamente a apertado ou desconfortável."],["amplo","Que oferece extensão ou espaço perceptivelmente generoso.","O vão amplo permite ver a praça desde a entrada.","Evite usar amplo quando só o enquadramento da lente aumenta a sensação de espaço."],["estreito","De largura pequena em relação à profundidade ou ao entorno.","O corredor estreito desemboca num salão mais amplo.","Use uma referência antes de afirmar que a largura é reduzida."],["alongado","Com comprimento relativamente grande diante da largura.","O balcão alongado conduz o olhar até a cozinha.","A lente pode acentuar proporções; observe por outro ângulo."],["baixo","De altura reduzida quando comparado a uma referência.","O muro baixo permite ver o jardim do outro lado.","Não invente metragem ou avaliação de segurança."],["esguio","De formato alto e relativamente estreito.","O poste esguio cria um eixo vertical ao lado do edifício.","A aparência esguia não comprova fragilidade estrutural."],["imponente","Que causa forte impressão visual pela escala ou composição.","As portas altas tornam a entrada visualmente imponente.","É percepção: mostre quais elementos justificam o adjetivo."],["discreto","Que se destaca pouco perante os demais elementos visuais.","O letreiro discreto quase se mistura à cor da parede.","Não presuma que a marca pretendia ocultá-lo."],["proporcional","Com relação equilibrada de dimensões entre as partes, segundo critério explicado.","A marquise parece proporcional à largura da entrada.","Equilíbrio visual é avaliação; explique o critério."]],"model":["Neste exercício, um volume alto se destaca ao lado de fachadas comerciais baixas.","O espaço de entrada de uma das lojas é compacto, com vitrine e porta muito próximas.","A diferença entre o edifício e as lojas fica mais clara quando incluímos pessoas no enquadramento como referência de escala.","Na minha leitura, essa variação de proporções ajuda a revelar camadas diferentes da paisagem urbana."],"swaps":[{"vague":"grande","options":["monumental","amplo","imponente"],"weak":"É um prédio grande.","strong":"É um edifício monumental: a torre ocupa todo o campo de visão a partir da calçada.","flag":true},{"vague":"pequeno","options":["compacto","estreito","baixo"],"weak":"A loja é pequena.","strong":"A loja é estreita: cabe apenas um balcão e duas pessoas lado a lado.","flag":true},{"vague":"enorme","options":["monumental","alongado","imponente"],"weak":"A avenida é enorme.","strong":"A avenida é ampla e alongada; atravessá-la exige duas fases de semáforo.","flag":true}]},{"scene":"Uma cafeteria iluminada pela manhã","focus":"Descreva direção, intensidade e qualidade da luz pelo que é visível, não pela temperatura presumida da lâmpada.","terms":[["difusa","Luz espalhada, com sombras pouco definidas.","A luz difusa ilumina a parede sem desenhar sombras duras.","Luz fraca e luz difusa não são sinônimos."],["direcional","Luz com direção de incidência predominante perceptível.","A iluminação direcional projeta sombras para a direita.","As sombras não identificam, por si, a fonte luminosa."],["rasante","Luz que incide em ângulo baixo sobre uma superfície.","A luz rasante destaca as irregularidades do revestimento.","Confirme a direção da incidência antes de usar o termo."],["contrastada","Com diferença marcada entre regiões claras e escuras.","A iluminação contrastada deixa a bancada clara e o corredor em sombra.","Não confunda contraste de iluminação com contraste de cores."],["suave","Luz com transição pouco abrupta entre claridade e sombra.","A luz suave preserva detalhes no rosto e na parede.","Suavidade não significa necessariamente pouca intensidade."],["dourada","Luz de aparência amarela ou âmbar.","A luz dourada colore os contornos dos prédios.","Não confirme horário ou temperatura de cor só pela aparência."],["indireta","Luz que chega após reflexão ou distribuição por outra superfície.","A luz indireta ilumina a mesa sem ofuscar o rosto.","Uma fonte fora do quadro não comprova iluminação indireta."],["irregular","Com distribuição desigual da iluminação na cena.","A luz irregular desenha manchas entre os galhos.","Não confunda diferença de iluminação com defeito da câmera."],["refletida","Luz que atinge uma superfície depois de rebater em outra.","Uma faixa de luz refletida aparece sobre o vidro da vitrine.","Não é possível concluir a fonte exata de um reflexo sem observação."],["natural","Proveniente de fontes luminosas naturais, como o sol.","A luz natural alcança as mesas perto da janela.","Aparência natural não prova ausência de luz artificial."]],"model":["Na cena de estudo, a luz entra pela janela e alcança a bancada.","Sobre a madeira, a incidência rasante evidencia veios e pequenas irregularidades.","Enquanto o balcão está iluminado, o corredor ao fundo permanece mais escuro, criando contraste.","Para mim, a passagem entre essas áreas de luz e sombra conduz o olhar até o preparo do café."],"swaps":[{"vague":"claro","options":["difusa","natural","refletida"],"weak":"O café é bem claro.","strong":"O café recebe luz natural difusa pelas janelas altas, sem sombras marcadas.","flag":false},{"vague":"escuro","options":["indireta","contrastada","irregular"],"weak":"O corredor é escuro.","strong":"O corredor tem iluminação indireta e irregular: só o fundo recebe luz.","flag":false},{"vague":"bonita","options":["dourada","rasante","suave"],"weak":"A luz da tarde estava bonita.","strong":"A luz dourada e rasante da tarde revela a textura dos tijolos.","flag":false}]},{"scene":"Uma vitrine com roupas, letreiros e objetos","focus":"Diferencie matiz, saturação e temperatura percebida; uma cor não prova a intenção de uma marca.","terms":[["monocromático","Que utiliza uma cor ou variações próximas de um mesmo matiz.","A vitrine utiliza uma composição quase monocromática em tons de azul.","Uma única cor não impede variação de luz e saturação."],["complementar","Relação entre cores opostas em determinado círculo cromático.","O vermelho do cartaz contrasta com detalhes verdes.","Considere o modelo cromático antes de classificar as cores."],["neutro","Tom pouco marcado cromaticamente, como cinza ou bege.","O fundo neutro evidencia as peças mais coloridas.","Cor neutra ainda produz efeito visual e simbólico."],["saturado","De cor intensa, com pouca aproximação ao cinza.","O letreiro vermelho saturado se destaca contra a parede clara.","Saturação não é sinônimo de luminosidade alta."],["dessaturado","De cor com intensidade reduzida, próxima de tons acinzentados.","Os verdes dessaturados produzem um contraste suave com o piso.","Não chame toda cor pastel de dessaturada sem considerar matiz e luminosidade."],["quente","Tonalidade percebida como próxima do vermelho, laranja ou amarelo.","Os tons quentes aproximam visualmente os móveis de madeira.","Temperatura visual não é temperatura física."],["frio","Tonalidade percebida como próxima do azul ou de certos verdes.","O azul frio do letreiro contrasta com a parede bege.","Não atribua uma sensação idêntica a todas as pessoas."],["terroso","De tonalidade associada visualmente a argila, areia, ferrugem ou terra.","Os tons terrosos da coleção aproximam visualmente casacos e acessórios.","Terroso nomeia a aparência, não a composição do corante."],["vibrante","Com presença visual intensa, frequentemente por saturação ou contraste.","Uma faixa vibrante de amarelo destaca a entrada.","Explique se o impacto vem de saturação, contraste ou área ocupada."],["gradual","Com transição progressiva de tom, cor ou intensidade.","O mural passa gradualmente de azul a cinza.","Blocos de cor separados não representam necessariamente gradiente."]],"model":["A vitrine do exercício reúne peças de tons terrosos e um letreiro colorido.","O vermelho mais saturado do letreiro se destaca diante das roupas de baixa intensidade cromática.","Comparada à parede neutra do fundo, a combinação das peças cria um conjunto cromático mais quente.","Minha impressão é que o contraste ajuda a organizar a atenção, mas a intenção da marca exigiria confirmação."],"swaps":[{"vague":"colorido","options":["saturado","vibrante","complementar"],"weak":"A vitrine é colorida.","strong":"A vitrine usa cores saturadas, com vermelho e verde em contraste complementar.","flag":true},{"vague":"sem graça","options":["neutro","dessaturado","monocromático"],"weak":"As roupas são sem graça.","strong":"As peças seguem uma paleta neutra e dessaturada, em cinzas e beges.","flag":true},{"vague":"chamativo","options":["vibrante","saturado","quente"],"weak":"O letreiro é chamativo.","strong":"O letreiro usa tons quentes e vibrantes que se destacam do concreto.","flag":true}]},{"scene":"Uma loja de objetos com vidro, cerâmica e metal","focus":"Associe textura e acabamento à superfície que você consegue observar; não deduza propriedades invisíveis.","terms":[["fosco","Com reflexão pouco especular, sem brilho definido.","O vaso fosco espalha a luz sem formar reflexos nítidos.","Fosco não significa áspero: acabamento e tato são dimensões distintas."],["polido","Com superfície tratada para reduzir irregularidades e refletir mais nitidamente.","O corrimão polido reflete formas do ambiente.","A aparência brilhante, isoladamente, não confirma o processo de fabricação."],["áspero","Que apresenta irregularidades ou atrito perceptíveis.","A pedra parece áspera pelas saliências reveladas pela luz.","Sem tocar, apresente aspereza como impressão visual."],["liso","Com superfície relativamente regular e sem saliências notáveis.","A mesa lisa reflete uma faixa de iluminação.","O enquadramento pode esconder irregularidades pequenas."],["granulado","Com grãos ou pontos pequenos visíveis na superfície.","O vaso tem uma textura granulada em close-up.","Grãos na imagem podem resultar do ruído da câmera."],["poroso","Com pequenos espaços ou aberturas na estrutura aparente.","A superfície porosa da peça deixa pequenas cavidades à vista.","Não afirme absorção de água sem teste ou especificação."],["acetinado","Com brilho moderado e difuso, entre fosco e brilhante.","O tecido acetinado recebe uma faixa discreta de luz.","O brilho não comprova composição de cetim ou seda."],["translúcido","Que permite passar luz sem formar imagem totalmente nítida.","O painel translúcido suaviza a visão do espaço interno.","Translúcido é diferente de transparente."],["metálico","Com aparência, brilho ou tonalidade associados a metal.","O acabamento metálico reflete a vitrine vizinha.","Aparência metálica não comprova o material da peça."],["aveludado","De aspecto visual macio, semelhante à superfície de veludo.","O revestimento aveludado espalha a luz sem reflexos fortes.","A aparência não comprova composição nem toque real."]],"model":["Na prateleira observamos superfícies de cerâmica, vidro e metal.","Um vaso de acabamento fosco contrasta com uma peça metálica que produz reflexos mais nítidos.","Enquanto o vidro deixa ver o fundo, o painel translúcido deixa passar luz e desfoca as formas.","Na minha avaliação, essa alternância de materiais dá ritmo à exposição sem precisar de muitos objetos."],"swaps":[{"vague":"macio","options":["acetinado","aveludado","polido"],"weak":"A cerâmica é macia.","strong":"A cerâmica tem acabamento acetinado: reflete pouco e parece suave ao toque.","flag":true},{"vague":"brilhante","options":["polido","metálico","translúcido"],"weak":"O balcão é brilhante.","strong":"O balcão de aço polido reflete as luminárias do teto.","flag":true},{"vague":"velho","options":["áspero","poroso","fosco"],"weak":"A parede é velha.","strong":"A parede tem reboco áspero e poroso, com pintura fosca descascando.","flag":true}]},{"scene":"Um salão de chá quase vazio","focus":"Atmosfera é interpretação fundamentada em pistas sensoriais; evite transformar impressão individual em verdade universal.","terms":[["acolhedor","Que transmite sensação subjetiva de recepção ou conforto.","Para mim, a iluminação baixa e os assentos próximos tornam o salão acolhedor.","Acolhedor é percepção; cite os elementos que a motivam."],["movimentado","Com múltiplas atividades ou deslocamentos observáveis.","O corredor parece movimentado durante a gravação da manhã.","Não represente um instante como padrão de todo o dia."],["contemplativo","Que favorece observação prolongada ou reflexão pessoal.","A vista do jardim me convida a um momento contemplativo.","A sensação é pessoal; não a atribua a todos os visitantes."],["intimista","Que favorece proximidade, recolhimento ou escala reduzida.","As mesas pequenas e a música baixa criam uma atmosfera intimista.","Não pressuponha que todos vivenciem o espaço da mesma forma."],["solene","De caráter formal ou cerimonioso.","O silêncio e o alinhamento dos assentos conferem solenidade à apresentação.","Silêncio sozinho não prova cerimônia."],["silencioso","Com poucos sons perceptíveis diante da referência utilizada.","O pátio está silencioso quando comparado à avenida.","Silencioso não é ausência absoluta de som."],["agitado","Com atividade intensa ou mudanças rápidas no ambiente.","O cruzamento parece agitado com ônibus e bicicletas passando.","Identifique quais ações sustentam essa impressão."],["arejado","Que transmite sensação de espaço aberto ou ventilado.","O salão parece arejado, com janelas abertas e teto alto.","Aparência não equivale à medição de ventilação ou qualidade do ar."],["concentrado","Reunido em uma área delimitada do espaço observado.","O movimento está concentrado nas bancas próximas à entrada.","A concentração visual não revela o público total."],["descontraído","De clima percebido como informal e pouco rígido.","As conversas espontâneas contribuem para um ambiente descontraído.","Evite atribuir estados emocionais a pessoas desconhecidas."]],"model":["Na situação imaginada, há poucas mesas ocupadas e música em volume discreto.","A disposição dos assentos e a iluminação baixa dão ao salão um aspecto intimista.","Ao contrário de um espaço de circulação rápida, este ambiente parece convidar a permanências mais longas.","Eu o descreveria como acolhedor, mas essa é minha impressão diante dos detalhes observados."],"swaps":[{"vague":"legal","options":["acolhedor","descontraído","arejado"],"weak":"O lugar é legal.","strong":"O salão é arejado e descontraído: mesas espaçadas e conversa em voz baixa.","flag":true},{"vague":"cheio","options":["movimentado","agitado","concentrado"],"weak":"O restaurante estava cheio.","strong":"O restaurante estava movimentado: todas as mesas ocupadas e fila na porta às 12h.","flag":false},{"vague":"tranquilo","options":["contemplativo","silencioso","intimista"],"weak":"O jardim é tranquilo.","strong":"O jardim é silencioso e contemplativo; ouve-se apenas a água do lago.","flag":false}]},{"scene":"Bicicletas cruzando uma praça","focus":"Identifique padrão, trajetória e velocidade percebida sem transformar um instante em estatística.","terms":[["gradual","Que se altera pouco a pouco num intervalo de tempo.","A sombra se desloca gradualmente sobre a calçada.","Um corte de edição não prova mudança contínua."],["fluido","Que ocorre sem interrupções ou mudanças bruscas evidentes.","O fluxo de ciclistas permanece fluido durante a tomada.","Uma cena breve não revela o padrão de todo o dia."],["brusco","Que se modifica rapidamente, com transição pouco perceptível.","Uma parada brusca interrompe o percurso da bicicleta.","Não deduza a causa da parada sem evidência."],["contínuo","Que segue sem interrupção visível durante o registro.","O movimento contínuo da esteira domina esta tomada.","Delimite o período observado, sem generalizar todo o funcionamento."],["intermitente","Que alterna períodos de atividade e pausa.","O som da campainha aparece de maneira intermitente.","Intermitente não significa necessariamente irregular."],["ritmado","Organizado em repetições com padrão de tempo identificável.","Os passos ritmados se alternam com o som das rodas.","O ritmo ouvido não informa velocidade exata."],["circular","Que descreve uma trajetória aproximadamente redonda.","Uma criança percorre um trajeto circular ao redor do canteiro.","Distinga trajetória observada de intenção do movimento."],["oscilante","Que alterna posição ou direção num movimento de vaivém.","Uma placa oscilante balança suavemente com o vento.","Oscilação não é a mesma coisa que rotação completa."],["acelerado","Que ganha velocidade ao longo de um intervalo observado.","O carrinho parece acelerar ao sair do corredor estreito.","Movimento rápido isolado não comprova aceleração."],["cadenciado","Que segue um ritmo identificável, marcado por repetições.","Os passos cadenciados se misturam ao ruído das rodas.","Cadenciado não exige velocidade constante."]],"model":["Na cena simulada, bicicletas atravessam uma praça por trajetos distintos.","O fluxo parece contínuo durante alguns segundos, enquanto o toque das campainhas é intermitente.","Quando comparamos a passagem das bicicletas ao deslocamento dos pedestres, percebemos ritmos diferentes no mesmo espaço.","Minha interpretação é que esses ritmos ajudam a contar a história da praça, mesmo sem uma entrevista."],"swaps":[{"vague":"rápido","options":["acelerado","brusco","contínuo"],"weak":"As bicicletas passam rápido.","strong":"As bicicletas passam em fluxo contínuo e acelerado quando o sinal abre.","flag":false},{"vague":"devagar","options":["gradual","cadenciado","fluido"],"weak":"As pessoas andam devagar.","strong":"Os praticantes de tai chi se movem de forma cadenciada e fluida.","flag":false},{"vague":"confuso","options":["intermitente","oscilante","brusco"],"weak":"O trânsito é confuso.","strong":"O trânsito é intermitente: avança em blocos e para de forma brusca.","flag":true}]},{"scene":"Uma fachada de edifício com entrada coberta","focus":"Nomeie elementos construtivos corretamente e não atribua data ou autoria sem pesquisa.","terms":[["fachada","Face exterior visível de uma construção.","A fachada apresenta aberturas regulares e uma entrada central.","O aspecto externo não comprova a idade do edifício."],["pórtico","Entrada ou passagem marcada por arcos, pilares ou moldura arquitetônica.","O pórtico da entrada separa o passeio do pátio interno.","Nem toda moldura de porta constitui um pórtico."],["marquise","Cobertura projetada sobre uma entrada ou trecho externo.","A marquise protege a faixa de acesso imediato ao prédio.","Não confunda marquise com qualquer sacada."],["cornija","Elemento saliente de arremate, geralmente horizontal, de fachada.","Uma cornija cria uma faixa de sombra abaixo da cobertura.","Não confunda cornija com marquise ou calha."],["vão","Abertura ou espaço livre entre partes de uma construção.","O vão da entrada enquadra uma pequena praça ao fundo.","O tamanho aparente não informa capacidade estrutural."],["platibanda","Mureta de fachada que se eleva acima do plano da cobertura.","A platibanda oculta o telhado visto da rua.","Não a identifique sem observar a extremidade superior da construção."],["pilotis","Pilares que sustentam a edificação, liberando parte do térreo.","O pavimento parece elevado por uma sequência de pilotis visíveis.","Verifique se são pilares estruturais antes de classificar."],["recuo","Afastamento em relação a um alinhamento de referência.","O recuo da porta cria um espaço protegido antes da entrada.","Recuo visível não prova conformidade com regras urbanísticas."],["arcada","Sequência de arcos arquitetônicos repetidos.","A arcada forma uma sucessão de sombras ao longo do corredor.","Um arco isolado não caracteriza necessariamente uma arcada."],["volumetria","Organização dos volumes e massas construídas.","A volumetria alterna um bloco alto com um corpo lateral mais baixo.","Não substitua descrição de volumes por rótulos de estilo sem evidência."]],"model":["O edifício da atividade tem fachada regular e entrada protegida por uma marquise.","A volumetria combina um bloco central mais alto e uma ala lateral de menor altura.","Diferentemente de uma construção com frente plana, esse conjunto projeta volumes em profundidades distintas.","Na minha leitura, observar esses recuos ajuda a entender a composição antes mesmo de procurar sua história."],"swaps":[{"vague":"prédio antigo","options":["fachada","cornija","arcada"],"weak":"É um prédio antigo bonito.","strong":"A fachada de pedra termina numa cornija ornamentada e abre-se em arcada no térreo.","flag":false},{"vague":"entrada","options":["pórtico","marquise","vão"],"weak":"A entrada é grande.","strong":"Um pórtico de colunas marca a entrada, protegido por uma marquise de vidro.","flag":false},{"vague":"moderno","options":["volumetria","pilotis","recuo"],"weak":"O edifício é moderno.","strong":"O edifício se apoia em pilotis e tem volumetria de blocos sobrepostos, com recuo da calçada.","flag":false}]},{"scene":"Uma esquina com comércio, calçada e árvores","focus":"Descreva o espaço público distinguindo observação direta de diagnóstico urbano.","terms":[["calçada","Faixa destinada principalmente à circulação de pedestres ao longo da via.","A calçada se estreita perto da banca, obrigando a desviar do expositor.","Uma imagem isolada não comprova acessibilidade no trajeto inteiro."],["travessia","Ponto ou ação de atravessar de um lado para outro da via.","A travessia sinalizada fica próxima à esquina.","Não presuma segurança apenas porque há pintura no piso."],["esquina","Local em que duas ruas ou frentes de um quarteirão se encontram.","Na esquina, uma cafeteria ocupa a frente voltada às duas vias.","Esquina não indica automaticamente o sentido do tráfego."],["quarteirão","Trecho urbano delimitado por ruas ou limites de circulação.","Neste quarteirão, as lojas se concentram no térreo.","Evite representar todo um bairro por um único quarteirão."],["praça","Espaço aberto de uso coletivo, com funções de circulação ou permanência.","A praça reúne bancos, canteiros e caminhos de pedestres.","Um pátio de aparência pública pode ter acesso privado."],["arborização","Conjunto de árvores presente ou implantado em um espaço.","A arborização acompanha quase todo o trecho enquadrado.","Não infira espécie, idade ou manejo sem fonte."],["fluxo","Movimento de pessoas ou veículos ao longo de um percurso.","O fluxo de pedestres aumenta junto à saída do metrô.","Sem contagem, descreva qualitativamente e delimite o período."],["mobiliário urbano","Conjunto de bancos, lixeiras, suportes e outros objetos do espaço público.","Os bancos compõem o mobiliário urbano junto ao canteiro.","Um objeto temporário não é necessariamente parte de mobiliário oficial."],["permeabilidade","Facilidade ou possibilidade de atravessar ou acessar um espaço.","As entradas em lados distintos aumentam a permeabilidade da galeria.","A permeabilidade visual não confirma acesso permitido."],["fachada ativa","Frente edificada com usos e aberturas que geram relação direta com a rua.","As vitrines e portas abertas criam uma fachada ativa voltada à calçada.","Um estabelecimento aberto no instante não prova vitalidade permanente."]],"model":["A esquina do exercício reúne lojas voltadas à calçada e árvores alinhadas à via.","Uma vitrine ocupa boa parte da fachada, enquanto a travessia fica próxima ao cruzamento.","Em comparação a uma frente fechada, as portas e vitrines oferecem mais pontos de contato visual com a rua.","Minha impressão é que esses elementos tornam a caminhada mais interessante; para avaliar acessibilidade, seria preciso observar o percurso completo."],"swaps":[{"vague":"movimentado","options":["fluxo","travessia","fachada ativa"],"weak":"A rua é movimentada.","strong":"A rua tem fluxo intenso de pedestres e fachada ativa: lojas abertas em toda a quadra.","flag":false},{"vague":"agradável","options":["arborização","mobiliário urbano","permeabilidade"],"weak":"A praça é agradável.","strong":"A praça tem arborização densa, bancos sombreados e permeabilidade para várias ruas.","flag":true},{"vague":"lugar","options":["esquina","quarteirão","praça"],"weak":"Fui a um lugar perto do metrô.","strong":"Fui a uma esquina a um quarteirão da saída 3 do metrô.","flag":false}]},{"scene":"Uma vitrine de alfaiataria contemporânea","focus":"Comunique moda com precisão técnica e diferencie avaliação estética de informação de fabricação.","terms":[["silhueta","Contorno geral que a peça ou conjunto cria no corpo.","O casaco constrói uma silhueta reta, com pouco ajuste na cintura.","Silhueta não determina por si só o público-alvo da marca."],["caimento","Modo como um tecido ou peça se acomoda e se movimenta no corpo.","O tecido forma pregas suaves e um caimento fluido na barra.","Uma foto estática não revela todo o comportamento em movimento."],["recorte","Linha ou peça resultante de cortes no desenvolvimento de roupa.","O recorte diagonal divide visualmente a frente do casaco.","Uma estampa pode simular recorte; verifique se há costura."],["pesponto","Costura visível realizada próxima a uma borda, emenda ou detalhe.","O pesponto aparente acompanha o contorno do bolso.","Não atribua função estrutural sem conhecer a construção."],["pregas","Dobras formadas no tecido para criar efeito ou volume.","As pregas abaixo do cós acrescentam volume à calça.","Dobras ocasionais não constituem necessariamente pregas de construção."],["aviamentos","Componentes complementares, como botões, zíperes e ilhoses.","Os aviamentos metálicos aparecem sobre a jaqueta escura.","Não confunda aviamentos com a fibra principal da peça."],["volume","Espaço visual ocupado pelo formato tridimensional da roupa.","O volume das mangas contrasta com a cintura ajustada.","A aparência não permite avaliar conforto ou estrutura interna."],["modelagem","Desenho técnico e geometria das partes que constituem a roupa.","A modelagem parece ampliar o volume nas mangas.","A aparência externa não confirma o molde interno."],["arremate","Finalização de costura, borda ou acabamento de um componente.","O arremate junto à abertura lateral é visualmente discreto.","Uma imagem não avalia resistência nem durabilidade de uma costura."],["acabamento","Tratamento final dado a superfícies, bordas e costuras.","O acabamento da gola parece regular no close-up.","A avaliação completa requer inspeção de avesso e construção."]],"model":["Na vitrine proposta, um casaco de silhueta reta aparece sobre uma calça ampla.","Um pesponto visível acompanha a borda do bolso e destaca o acabamento.","Enquanto o casaco mantém linhas mais estruturadas, o tecido da calça forma dobras suaves.","Na minha avaliação, o interesse visual está na relação entre rigidez e fluidez; para julgar a modelagem, precisaria examinar a peça."],"swaps":[{"vague":"elegante","options":["silhueta","caimento","modelagem"],"weak":"O terno é elegante.","strong":"O terno tem silhueta ajustada e caimento reto, sem rugas nas costas.","flag":true},{"vague":"bem-feito","options":["acabamento","pesponto","arremate"],"weak":"A peça é bem-feita.","strong":"O pesponto é regular e o arremate interno esconde as costuras.","flag":true},{"vague":"diferente","options":["recorte","volume","pregas"],"weak":"O vestido é diferente.","strong":"O vestido tem recortes assimétricos e pregas que criam volume no quadril.","flag":true}]},{"scene":"Uma refeição recém-servida","focus":"Separe sensações pessoais, técnicas observáveis e ingredientes que ainda precisam ser confirmados.","terms":[["crocante","Que se rompe com resistência e produz estalos ao mastigar.","A cobertura ficou crocante ao primeiro corte e ao provar.","Fotografia isolada não comprova crocância."],["cremoso","De consistência macia e coesa, fácil de espalhar.","O molho cremoso envolve a massa e não escorre rapidamente.","Textura não prova a presença de creme de leite."],["fibroso","Com estruturas alongadas que se percebem ao cortar ou mastigar.","A fruta aberta revela uma polpa fibrosa.","Fibroso não equivale a medida nutricional de fibras."],["untuoso","De textura gordurosa e deslizante percebida ao paladar.","O molho tem sensação untuosa e recobre a colher.","Untuoso descreve percepção; não determine um ingrediente sem confirmação."],["ácido","Que apresenta sensação gustativa de acidez.","O sabor ácido aparece no final de cada garfada.","Acidez percebida não mede o pH."],["adocicado","Com presença suave ou secundária de sabor doce.","O molho tem um fundo adocicado depois da acidez.","Não atribua açúcar adicionado sem confirmar os ingredientes."],["defumado","Com aroma ou sabor associado à fumaça.","Percebi notas defumadas no aroma do prato.","Notas defumadas não comprovam que houve defumação real."],["aromático","Com cheiro perceptível e característico.","O chá aromático perfuma o espaço antes da degustação.","Aroma não confirma todos os ingredientes do preparo."],["aveludado","De textura lisa e macia percebida na boca.","A sopa apresenta textura aveludada e uniforme.","Não deduza ingredientes gordurosos apenas pela sensação."],["persistente","De sabor ou aroma que permanece após a degustação.","O toque cítrico continua persistente após o último gole.","A persistência é percepção individual, não uma medição universal."]],"model":["Na cena da atividade, um prato chega à mesa com molho espesso e cobertura dourada.","Ao provar, a cobertura parece crocante e o molho oferece sensação untuosa.","Comparando as duas texturas, uma se rompe ao mastigar enquanto a outra permanece mais envolvente.","Para mim, esse contraste é o aspecto mais marcante do prato, mas seus ingredientes devem ser confirmados no cardápio ou com a cozinha."],"swaps":[{"vague":"gostoso","options":["aromático","untuoso","persistente"],"weak":"O caldo é gostoso.","strong":"O caldo é aromático e untuoso, com sabor de gengibre persistente.","flag":true},{"vague":"delicioso","options":["crocante","cremoso","defumado"],"weak":"O bolinho é delicioso.","strong":"O bolinho é crocante por fora e cremoso por dentro.","flag":true},{"vague":"forte","options":["ácido","defumado","persistente"],"weak":"O molho tem um gosto forte.","strong":"O molho é ácido, com vinagre escuro, e deixa um retrogosto defumado.","flag":false}]},{"scene":"O interior de uma estação com anúncios sonoros","focus":"Descrever som exige distinguir fonte, ritmo e fenômenos acústicos sem inventar medidas.","terms":[["ressonância","Reforço de vibrações sonoras em determinadas frequências ou materiais.","Uma ressonância grave acompanha o ruído no corredor subterrâneo.","Não confunda ressonância com repetição audível típica de eco."],["reverberação","Persistência breve de sons refletidos por várias superfícies.","A voz do aviso permanece audível por instantes na forma de reverberação.","Reverberação não é sempre eco separado."],["eco","Repetição audível de um som por reflexão com atraso perceptível.","Um chamado se repete como eco no corredor vazio.","Não chame todo som prolongado de eco."],["sussurro","Fala muito baixa, com emissão de ar predominante.","Um sussurro se destaca durante a pausa da música.","Evite captar ou publicar conversas privadas sem permissão."],["estalo","Som breve e seco provocado por contato ou ruptura.","Um estalo acompanha o fechamento da caixa de madeira.","O som sozinho não confirma o material que o produziu."],["zumbido","Som contínuo, geralmente grave ou vibratório.","Um zumbido discreto acompanha o funcionamento do equipamento.","Evite inferir qual máquina o produziu se não a identificou."],["ruído","Som secundário ou indesejado em relação ao sinal principal.","O ruído do sistema de ventilação cobre parte da entrevista.","Ruído também pode transmitir contexto e não ser falha técnica."],["cadência","Organização rítmica de uma sequência sonora.","A cadência dos avisos alterna fala e pequenos intervalos.","Cadência não é sinônimo de volume."],["intensidade","Grau de força do som ou de sua percepção auditiva.","A intensidade percebida do tráfego cresce perto da avenida.","Não informe decibéis sem medição instrumental."],["silêncio","Ausência ou redução significativa de som num contexto.","Após o aviso, alguns segundos de silêncio ocupam a gravação.","Silêncio na edição pode resultar de corte e não do ambiente."]],"model":["A estação simulada apresenta avisos ao público e um ruído contínuo ao fundo.","Em alguns pontos do corredor, o anúncio parece permanecer por instantes devido à reverberação.","Enquanto a voz surge em intervalos, o zumbido do ambiente se mantém mais constante durante a gravação.","Na minha escuta, esse contraste de duração ajuda a transmitir a escala do espaço sem precisar nomear equipamentos desconhecidos."],"swaps":[{"vague":"barulhento","options":["ruído","reverberação","intensidade"],"weak":"A estação é barulhenta.","strong":"A estação tem ruído constante, e a reverberação do teto alto aumenta a intensidade dos anúncios.","flag":true},{"vague":"silencioso","options":["silêncio","sussurro","zumbido"],"weak":"O museu é silencioso.","strong":"No museu, o silêncio só é interrompido pelo zumbido do ar-condicionado.","flag":false},{"vague":"som","options":["estalo","cadência","eco"],"weak":"Dava para ouvir um som.","strong":"Ouvia-se o estalo regular das rodas do carrinho, numa cadência de dois tempos.","flag":false}]},{"scene":"Uma fotografia de rua feita no fim da tarde","focus":"Explique fotografia com termos técnicos que correspondam à imagem; informe configurações apenas quando conhecidas.","terms":[["contraluz","Situação em que a fonte de luz está atrás do assunto em relação à câmera.","A pessoa foi fotografada em contraluz, com o sol fora do enquadramento.","Contraluz não implica obrigatoriamente silhueta."],["primeiro plano","Parte da cena situada visualmente mais perto da câmera.","A bicicleta em primeiro plano ajuda a dar escala ao edifício.","Um objeto em primeiro plano não precisa estar em foco."],["profundidade de campo","Extensão da cena que parece aceitavelmente nítida.","A profundidade de campo reduzida destaca o rosto contra o fundo desfocado.","Não confunda profundidade de campo com distância focal isoladamente."],["perspectiva","Relação visual de tamanhos e posições que sugere profundidade.","As linhas convergentes do corredor reforçam a perspectiva.","Perspectiva não informa automaticamente o tipo de lente."],["enquadramento","Seleção dos elementos incluídos e excluídos dos limites da imagem.","O enquadramento inclui a bicicleta à esquerda como referência de escala.","Não atribua intenção do fotógrafo sem entrevistá-lo."],["reflexo","Imagem ou luz devolvida por uma superfície refletora.","O reflexo das luzes surge sobre o piso molhado.","Não identifique a fonte se ela estiver fora do enquadramento."],["desfoque","Ausência ou redução de nitidez em parte da imagem.","O desfoque do fundo destaca a expressão do entrevistado.","Pode resultar de foco, movimento ou edição: não presuma a causa."],["silhueta","Contorno de figura percebido pelo contraste com o fundo.","A silhueta do pedestre se destaca contra a vitrine iluminada.","Silhueta não implica perda definitiva dos detalhes originais."],["panorâmica","Visão ampla ou movimento de câmera que percorre a cena.","Uma panorâmica lenta apresenta o entorno da praça.","Diferencie foto panorâmica de movimento de câmera."],["exposição","Quantidade de luz registrada numa captura fotográfica.","A exposição preserva detalhes nas vitrines mais claras.","Sem metadados, não invente ajustes de ISO, abertura e obturador."]],"model":["A fotografia do exercício mostra um pedestre diante de uma rua iluminada pelo sol baixo.","O enquadramento coloca a figura em primeiro plano e deixa fachadas desfocadas ao fundo.","Comparada a uma imagem com todos os planos nítidos, essa escolha dirige mais atenção à pessoa.","Na minha leitura, a relação entre figura e ambiente dá unidade à cena; a intenção do fotógrafo precisaria ser confirmada."],"swaps":[{"vague":"foto boa","options":["enquadramento","exposição","profundidade de campo"],"weak":"Tirei uma foto boa.","strong":"O enquadramento isola o vendedor, e a pouca profundidade de campo desfoca a fila.","flag":false},{"vague":"escura","options":["contraluz","silhueta","exposição"],"weak":"A foto ficou escura.","strong":"Em contraluz, o ciclista virou silhueta porque a exposição foi feita para o céu.","flag":false},{"vague":"embaçada","options":["desfoque","primeiro plano","perspectiva"],"weak":"A foto ficou embaçada.","strong":"O desfoque no primeiro plano direciona o olhar para a perspectiva da rua.","flag":false}]},{"scene":"Uma chegada a um bairro desconhecido","focus":"Aprenda a nomear o que sentiu sem projetar emoções sobre moradores e outras pessoas.","terms":[["surpresa","Reação ao encontro de algo não previsto.","Fiquei surpreso ao encontrar uma galeria dentro da estação.","Descreva sua surpresa, não a de todos os visitantes."],["curiosidade","Interesse em investigar algo ainda não compreendido.","A fachada despertou minha curiosidade sobre a história do lugar.","Curiosidade formula perguntas, não comprova respostas."],["encantamento","Admiração afetiva intensa diante de uma experiência.","Senti encantamento ao ver a luz atravessando as árvores.","Trata-se de reação pessoal e não de qualidade universal."],["estranhamento","Sensação de distância ou surpresa diante do que não é familiar.","Senti estranhamento ao encontrar uma organização de lojas diferente da habitual.","Estranhamento descreve sua reação, não um defeito do lugar."],["familiaridade","Percepção subjetiva de reconhecimento ou proximidade.","A disposição das mesas me trouxe uma sensação de familiaridade.","Não presuma experiência idêntica para outros visitantes."],["nostalgia","Emoção de lembrança afetiva do passado.","A música despertou nostalgia de encontros de família.","Nostalgia depende de memória pessoal; não é característica objetiva da música."],["calma","Estado de tranquilidade vivenciado numa situação.","Senti calma durante a caminhada pelo jardim.","Pouco movimento não prova que outras pessoas sintam o mesmo."],["expectativa","Antecipação mental sobre algo que ainda vai acontecer.","Cheguei ao mercado com expectativa de descobrir novos sabores.","Distinga o que esperava encontrar do que realmente encontrou."],["admiração","Apreço ou respeito diante de algo considerado notável.","Senti admiração pelo cuidado visível nos detalhes da peça.","O sentimento não confirma autoria ou qualidade técnica."],["ambivalência","Presença simultânea de sentimentos ou avaliações diferentes.","Senti ambivalência entre entusiasmo pela novidade e cautela diante do desconhecido.","Evite usar ambivalência como mero sinônimo de dúvida factual."]],"model":["Cheguei ao bairro da situação proposta e encontrei lojas com disposições que não reconheci de imediato.","Minha primeira reação foi de estranhamento, mas a música de uma cafeteria trouxe familiaridade.","Em vez de classificar o lugar como estranho, consigo comparar essa reação às experiências que já vivi em outros bairros.","Essa mistura de surpresa e reconhecimento descreve minha percepção pessoal, não uma característica universal do bairro."],"swaps":[{"vague":"incrível","options":["admiração","encantamento","surpresa"],"weak":"Foi incrível chegar lá.","strong":"Senti surpresa ao ver o bairro antigo atrás das torres, e depois admiração pelos detalhes.","flag":true},{"vague":"esquisito","options":["estranhamento","ambivalência","curiosidade"],"weak":"Foi esquisito no começo.","strong":"No início senti estranhamento; com o tempo, a curiosidade venceu.","flag":true},{"vague":"bom","options":["calma","familiaridade","nostalgia"],"weak":"Foi bom estar ali.","strong":"A rua me deu uma sensação de familiaridade e calma, quase nostalgia.","flag":false}]},{"scene":"Uma praça com fonte, bancos e canteiros","focus":"Organize o olhar do público usando posições relativas claras e mantendo a orientação da câmera.","terms":[["adjacente","Que fica ao lado, com proximidade direta.","O banco adjacente ao canteiro está parcialmente na sombra.","Não use adjacente para elementos distantes no enquadramento."],["ao fundo","Na parte visualmente mais distante da composição.","Ao fundo, uma escadaria conduz à praça elevada.","A profundidade na imagem depende da perspectiva mostrada."],["na diagonal","Em orientação oblíqua aos eixos de referência da composição.","Um caminho corta a praça na diagonal, da esquerda para a direita.","Indique qual enquadramento está sendo usado como referência."],["em primeiro plano","Em posição próxima ao observador na composição visual.","Em primeiro plano, uma flor introduz a paisagem do jardim.","Proximidade não significa necessariamente protagonismo narrativo."],["paralelo","Em direção semelhante sem encontro no espaço descrito.","Duas fileiras paralelas de árvores acompanham a avenida.","A perspectiva fotográfica pode fazer linhas paralelas convergirem."],["sobreposto","Que aparece ou se posiciona parcialmente sobre outro elemento.","A silhueta da árvore fica sobreposta à fachada na imagem.","Sobreposição visual não implica contato físico."],["alinhado","Disposto segundo uma linha ou eixo visual.","Os postes aparecem alinhados na borda da calçada.","Alinhamento aparente não atesta precisão geométrica."],["intercalado","Distribuído em alternância entre outros elementos.","Os bancos aparecem intercalados com pequenos canteiros.","Confirme se existe de fato uma sequência alternada."],["centralizado","Situado próximo ao centro do referencial escolhido.","O relógio centralizado organiza a composição da parede.","Centro fotográfico pode ser diferente do centro físico do objeto."],["nas extremidades","Localizado nas partes mais afastadas de um objeto ou quadro.","Duas luminárias nas extremidades deixam o centro livre.","Especifique se fala das extremidades do objeto ou da imagem."]],"model":["Na cena simulada, uma fonte ocupa o centro do enquadramento e há bancos nos dois lados.","Um canteiro fica adjacente ao primeiro banco; ao fundo, vemos uma pequena escadaria.","Enquanto a fonte atrai o olhar imediatamente, os bancos intercalados com canteiros conduzem a atenção pelas laterais.","Minha impressão é que essa organização ajuda o visitante a perceber diferentes zonas da praça, embora a experiência varie com o trajeto."],"swaps":[{"vague":"perto","options":["adjacente","em primeiro plano","sobreposto"],"weak":"A banca fica perto da fonte.","strong":"A banca é adjacente à fonte, do lado leste da praça.","flag":false},{"vague":"atrás","options":["ao fundo","sobreposto","nas extremidades"],"weak":"Tem prédios atrás.","strong":"Ao fundo, as torres aparecem sobrepostas aos telhados baixos.","flag":false},{"vague":"espalhado","options":["intercalado","alinhado","na diagonal"],"weak":"Os bancos ficam espalhados.","strong":"Os bancos estão intercalados com canteiros e alinhados na diagonal.","flag":false}]},{"scene":"Um mercado abrindo para o movimento da manhã","focus":"A cronologia deve respeitar a sequência observada; não confunda tempo do vídeo com horário real.","terms":[["gradualmente","De modo progressivo, em pequenas mudanças sucessivas.","O movimento de pessoas aumentou gradualmente ao longo da filmagem.","Uma mudança entre dois cortes não prova progressão contínua."],["repentinamente","De forma inesperada ou abrupta em relação à sequência observada.","Uma rajada repentinamente deslocou as folhas da calçada.","Não use repentinamente para o que já foi apresentado como previsível."],["ao amanhecer","No período inicial de claridade do dia.","Ao amanhecer, a luz revela gradualmente os letreiros da rua.","Confirme o período com informação confiável do registro."],["no intervalo","Durante uma pausa entre dois acontecimentos.","No intervalo entre anúncios, o corredor parece mais silencioso.","Não monte cenas separadas como se fossem simultâneas."],["enquanto isso","Conector que marca simultaneidade de ações.","O funcionário organiza as caixas; enquanto isso, clientes chegam.","Não afirme simultaneidade se as cenas foram gravadas em momentos diferentes."],["mais adiante","Em ponto posterior do trajeto ou do discurso.","Mais adiante, a calçada se estreita perto da banca.","Explique se a referência é espacial ou temporal."],["posteriormente","Em momento que ocorre depois do fato mencionado.","Posteriormente, o vendedor explicou a origem do objeto.","Uma sequência de edição pode não refletir a ordem real."],["anteriormente","Em momento que ocorreu antes da referência atual.","Anteriormente, tínhamos observado a mesma solução em outra loja.","Indique o registro anterior quando isso afetar a compreensão."],["na sequência","Expressão que introduz o acontecimento posterior.","Na sequência, a porta foi aberta e as primeiras pessoas entraram.","A ordem da edição não garante a ordem dos acontecimentos."],["ao final","No encerramento de uma sequência definida.","Ao final da caminhada, retornamos ao ponto de partida.","Não generalize a conclusão para além da sequência observada."]],"model":["Na gravação imaginada, os comerciantes organizam produtos antes da chegada dos clientes.","Gradualmente, mais pessoas aparecem na passagem central, enquanto um funcionário termina de arrumar as caixas.","Na sequência, o ritmo fica mais intenso do que nos primeiros instantes filmados.","Minha leitura é que essa progressão oferece uma boa estrutura de história, desde que a montagem preserve a cronologia real."],"swaps":[{"vague":"depois","options":["posteriormente","na sequência","mais adiante"],"weak":"Depois, o mercado encheu.","strong":"Na sequência, por volta das 7h, os primeiros clientes chegaram.","flag":false},{"vague":"de repente","options":["repentinamente","no intervalo","enquanto isso"],"weak":"De repente, todo mundo saiu.","strong":"Repentinamente, quando a chuva começou, as bancas cobriram as mercadorias.","flag":false},{"vague":"aos poucos","options":["gradualmente","ao amanhecer","ao final"],"weak":"Aos poucos a rua mudou.","strong":"Gradualmente, ao amanhecer, as portas de aço foram se abrindo uma a uma.","flag":false}]},{"scene":"Um vendedor de frutas atrás da banca, no fim da manhã","focus":"Descreva traços visíveis com neutralidade. Aparência não revela idade exata, origem, renda, profissão nem estado de saúde — e quem aparece em destaque precisa consentir.","terms":[["estatura","Altura de uma pessoa percebida em relação ao ambiente ou a outras pessoas.","De estatura mediana, ele alcança o toldo da banca sem precisar se esticar.","Prefira comparações com o ambiente a números; não use estatura como qualidade ou defeito."],["compleição","Conjunto da constituição física: largura dos ombros, estrutura e proporções do corpo.","De compleição esguia, ela se move com facilidade entre as caixas empilhadas.","Descreva sem julgar o corpo; evite termos depreciativos e associações com saúde ou caráter."],["grisalho","Cabelo ou barba com fios brancos ou cinzentos misturados aos de cor original.","O cabelo grisalho aparece sob o boné azul quando ele se abaixa.","Fios brancos não indicam idade exata; não deduza quantos anos a pessoa tem."],["cacheado","Cabelo com ondas fechadas que formam cachos definidos.","Os cabelos cacheados estão presos no alto da cabeça com uma presilha.","Descreva o cabelo sem associá-lo a origem étnica ou a julgamentos de arrumação."],["rabo de cavalo","Penteado em que o cabelo é preso na parte de trás da cabeça e cai em mecha única.","Um rabo de cavalo baixo balança a cada vez que ela vira para atender alguém.","Penteado é escolha momentânea; não o use para supor personalidade ou ocupação."],["barbado","Que tem barba crescida, cheia ou aparada.","O homem barbado confere o troco contando as moedas na palma da mão.","Barba não indica religião, nacionalidade nem descuido; descreva apenas o que se vê."],["rugas de expressão","Linhas na pele formadas pela repetição de movimentos do rosto, como sorrir ou franzir.","Quando ele ri, rugas de expressão se acentuam ao redor dos olhos.","Rugas não definem idade com precisão; evite transformar a observação em comentário sobre envelhecimento."],["tatuagem","Desenho permanente feito na pele com tinta.","Uma tatuagem de folhas contorna o pulso esquerdo da vendedora.","Não interprete o significado de uma tatuagem sem perguntar; evite closes sem consentimento."],["uniformizado","Que veste roupa padronizada de uma empresa, serviço ou instituição.","Um funcionário uniformizado, de colete laranja, recolhe as caixas vazias.","Uniforme indica vínculo provável, não confirma cargo; verifique antes de afirmar a função."],["acessório","Objeto usado junto ao corpo ou à roupa, como óculos, relógio, colar ou boné.","O único acessório visível é um relógio de pulseira de couro gasta.","Acessórios não comprovam renda ou estilo de vida; descreva-os sem inferir status social."]],"model":["Atrás da banca, um homem de estatura mediana organiza laranjas em pirâmide sobre um caixote.","Ele está uniformizado com um avental verde, e o cabelo grisalho aparece sob um boné azul desbotado.","Enquanto o colega ao lado usa rabo de cavalo e fala com os clientes, ele trabalha em silêncio, concentrado nas frutas.","Minha impressão é que a banca funciona em dupla: um cuida da exposição, o outro do atendimento — algo que só uma conversa confirmaria."],"swaps":[{"vague":"bonita","options":["compleição","cacheado","acessório"],"weak":"A vendedora é bonita.","strong":"De compleição esguia, a vendedora tem cabelos cacheados presos e usa um único acessório: brincos de argola.","flag":true},{"vague":"velhinho","options":["grisalho","rugas de expressão","estatura"],"weak":"Um velhinho vende frutas.","strong":"Um homem grisalho, de estatura baixa, vende frutas; rugas de expressão marcam o rosto quando sorri.","flag":true},{"vague":"arrumado","options":["uniformizado","acessório","rabo de cavalo"],"weak":"Ele estava bem arrumado.","strong":"Ele estava uniformizado, com camisa passada, e usava como acessório um relógio de metal.","flag":true}]},{"scene":"Duas pessoas conversando num banco de praça","focus":"Descreva o movimento do rosto e das mãos, não a emoção. Gestos variam entre culturas e situações: o que parece irritação pode ser concentração.","terms":[["semblante","Aspecto geral do rosto em determinado momento.","O semblante dela permanece sereno enquanto o amigo fala rápido.","Semblante é aparência, não sentimento confirmado; evite afirmar o estado interior."],["cenho franzido","Testa contraída, com as sobrancelhas aproximadas.","Com o cenho franzido, ele lê a mensagem no celular duas vezes.","Franzir pode indicar dúvida, sol forte ou esforço de leitura — não necessariamente raiva."],["sorriso contido","Sorriso discreto, com os lábios pouco abertos.","Um sorriso contido aparece quando ela ouve a resposta.","Não deduza timidez ou ironia apenas pelo tamanho do sorriso."],["olhar fixo","Olhar mantido por um tempo no mesmo ponto.","Ele mantém o olhar fixo na fonte enquanto escuta.","Olhar fixo pode ser atenção, distração ou reflexão; descreva a direção, não a intenção."],["gesticulação","Uso frequente das mãos e dos braços para acompanhar a fala.","A gesticulação ampla dele desenha no ar o caminho até a estação.","Intensidade de gestos varia culturalmente; não a interprete como nervosismo ou exagero."],["aceno","Movimento curto de mão ou cabeça para cumprimentar, concordar ou chamar.","Um aceno de cabeça encerra a conversa antes de ela se levantar.","O sentido do aceno depende do contexto; confirme se é concordância ou apenas despedida."],["dar de ombros","Levantar e baixar os ombros, gesto que costuma indicar dúvida ou indiferença.","Diante da pergunta, ele dá de ombros e aponta para o mapa.","O gesto não tem o mesmo sentido em todas as culturas; trate a interpretação como hipótese."],["braços cruzados","Postura com os braços dobrados à frente do peito.","Ela escuta de braços cruzados, com o casaco fechado até o pescoço.","Braços cruzados podem ser frio ou conforto; não afirme que a pessoa está fechada ou na defensiva."],["sobrancelhas arqueadas","Sobrancelhas erguidas, formando um arco acima dos olhos.","Com as sobrancelhas arqueadas, ela repete o preço em voz alta.","Pode indicar surpresa, pergunta ou ênfase; o contexto da fala ajuda a distinguir."],["expressivo","Que demonstra muito movimento no rosto e no corpo ao se comunicar.","O rosto expressivo do senhor acompanha cada parte da história que conta.","Ser expressivo é estilo de comunicação, não sinal de exagero ou falta de seriedade."]],"model":["No banco da praça, duas pessoas conversam lado a lado, voltadas para a fonte.","Ele fala com gesticulação ampla, enquanto ela escuta de braços cruzados, com semblante sereno.","Diferentemente do amigo, que muda de expressão a cada frase, ela responde apenas com acenos curtos e um sorriso contido.","Para mim, o contraste sugere ritmos diferentes de conversa, não desacordo — mas eu não sei o que cada um sentia."],"swaps":[{"vague":"bravo","options":["cenho franzido","braços cruzados","olhar fixo"],"weak":"Ele parecia bravo.","strong":"Ele manteve o cenho franzido e o olhar fixo no celular, de braços cruzados — o motivo eu não sei.","flag":false},{"vague":"feliz","options":["sorriso contido","expressivo","semblante"],"weak":"Ela estava feliz.","strong":"Ela sorria abertamente, com o rosto expressivo, e o semblante ficou mais leve ao fim da conversa.","flag":false},{"vague":"animado","options":["gesticulação","expressivo","sobrancelhas arqueadas"],"weak":"Ele falava todo animado.","strong":"Ele falava com gesticulação ampla, sobrancelhas arqueadas e rosto expressivo a cada frase.","flag":false}]},{"scene":"Um entregador esperando o semáforo abrir, ao lado de pedestres","focus":"Postura e passo revelam relação com o espaço e com o tempo. Não conclua cansaço, pressa ou tristeza sem outros indícios.","terms":[["ereto","Com o tronco e a cabeça alinhados na vertical.","Ereto sobre a scooter, ele observa o semáforo com as mãos no guidão.","Postura ereta não prova confiança nem disciplina; descreva a forma do corpo."],["curvado","Com o tronco inclinado para a frente ou as costas arqueadas.","Curvada sobre o carrinho, a senhora empurra sacolas pela calçada.","Curvatura pode resultar de carga, frio ou hábito; evite associá-la a desânimo."],["apoiado","Com o peso do corpo sustentado em algo, como parede, grade ou objeto.","Apoiado na grade, um rapaz espera com o capacete no braço.","Apoiar-se não indica preguiça; descreva o ponto de apoio."],["agachado","Com os joelhos dobrados e o corpo próximo do chão.","Agachado, o entregador ajusta a corrente da bicicleta.","Diga o que a pessoa faz agachada; a posição sozinha não explica a ação."],["inclinado","Com o corpo pendendo levemente para um lado ou para a frente.","Inclinado para a frente, ele tenta ler o número do prédio do outro lado.","Inclinação pode ser movimento passageiro; registre o momento observado."],["passo apressado","Caminhada rápida, com passadas curtas e frequentes.","Com passo apressado, um grupo atravessa antes de o sinal fechar.","Passo rápido pode ser hábito local; não deduza atraso ou ansiedade."],["passo arrastado","Caminhada lenta, com os pés pouco levantados do chão.","Um homem segue de passo arrastado, de chinelos, rumo ao mercado.","Evite interpretar o passo como sinal de doença ou desânimo."],["imóvel","Sem se mover durante o intervalo observado.","Imóvel na esquina, uma mulher segura o guarda-chuva fechado.","Imobilidade é relativa ao tempo de observação; diga por quanto tempo observou."],["desenvolto","Que se movimenta com facilidade e naturalidade no espaço.","Desenvolto, o entregador desvia dos pedestres sem reduzir muito a velocidade.","Desenvoltura não comprova experiência profissional; é impressão de movimento."],["hesitante","Que interrompe ou retoma o movimento, como quem decide o caminho.","Hesitante, o turista dá dois passos, para e consulta o mapa outra vez.","Hesitação aparente pode ser cautela ou atenção ao trânsito; trate como hipótese."]],"model":["Na esquina, um entregador espera o semáforo sentado na scooter, com o capacete preso no guidão.","Ereto e imóvel, ele observa o sinal; ao lado, uma senhora curvada apoia as mãos num carrinho de compras.","Quando o sinal abre, ele parte desenvolto entre os carros, enquanto os pedestres atravessam com passo apressado.","Minha impressão é que a esquina tem dois tempos — o das rodas e o dos pés — convivendo no mesmo minuto."],"swaps":[{"vague":"cansado","options":["curvado","passo arrastado","apoiado"],"weak":"Ele parecia cansado.","strong":"Ele seguia curvado, de passo arrastado, e parou apoiado no poste por um minuto.","flag":false},{"vague":"perdido","options":["hesitante","inclinado","imóvel"],"weak":"O turista estava perdido.","strong":"Hesitante, o turista parou imóvel na esquina e se inclinou para ler a placa.","flag":false},{"vague":"rápido","options":["passo apressado","desenvolto","ereto"],"weak":"Ela andava rápido.","strong":"Ela andava de passo apressado, ereta, desviando desenvolta dos carrinhos de compras.","flag":false}]},{"scene":"Uma banca de antiguidades montada numa calçada","focus":"Marcas de uso contam histórias, mas não provam idade, valor nem autenticidade. Descreva o desgaste antes de imaginar a origem.","terms":[["desgastado","Com a superfície gasta pelo uso ou pelo tempo.","O cabo desgastado da chaleira perdeu a cor onde as mãos o seguravam.","Desgaste não indica idade exata nem antiguidade autêntica."],["intacto","Sem quebras, rachaduras ou partes faltando.","A tampa de porcelana está intacta, apesar da poeira acumulada.","Intacto descreve a integridade visível, não o funcionamento."],["lascado","Com pequenos pedaços perdidos na borda ou na superfície.","A borda lascada da tigela revela o barro claro sob o esmalte azul.","Diferencie lasca de rachadura: a lasca perde material; a rachadura abre uma fenda."],["enferrujado","Coberto por ferrugem, a oxidação avermelhada do ferro.","O cadeado enferrujado ainda prende a corrente da bicicleta.","Ferrugem indica exposição à umidade, não necessariamente abandono."],["remendado","Consertado com material ou técnica visível, diferente do original.","O guarda-chuva remendado tem uma faixa de tecido mais escura entre as varetas.","O conserto mostra cuidado ou necessidade; não deduza a situação econômica do dono."],["artesanal","Feito à mão ou em pequena escala, com variações entre peças.","As xícaras artesanais têm alças de tamanhos ligeiramente diferentes.","Não afirme que algo é artesanal só pela aparência rústica; confirme com quem vende."],["industrializado","Produzido em série por processo de fábrica, com peças idênticas.","As garrafas industrializadas se repetem na prateleira com o mesmo rótulo.","Produção em série não significa baixa qualidade."],["utilitário","Feito principalmente para cumprir uma função prática.","Um banquinho utilitário de plástico serve de apoio para as caixas.","Objetos utilitários também podem ter valor estético ou afetivo."],["ornamental","Feito principalmente para enfeitar ou decorar.","Um vaso ornamental, sem flores, ocupa o centro da mesa.","Função decorativa pode coexistir com uso prático; observe como o objeto é usado."],["portátil","Leve e pequeno o bastante para ser carregado com facilidade.","Um rádio portátil toca baixo ao lado do caixa.","Portátil descreve o tamanho e o peso, não a tecnologia do objeto."]],"model":["Sobre um pano estendido na calçada, há chaleiras, xícaras, cadeados e um rádio portátil.","Uma chaleira de metal tem o cabo desgastado, e ao lado uma tigela de esmalte azul aparece com a borda lascada.","Enquanto as xícaras artesanais variam de tamanho, as garrafas industrializadas se repetem com o mesmo rótulo.","Para mim, a banca é um arquivo de usos cotidianos — mas idade e procedência de cada peça só o vendedor poderia informar."],"swaps":[{"vague":"antigo","options":["desgastado","enferrujado","remendado"],"weak":"É um objeto antigo.","strong":"O objeto está desgastado, com partes enferrujadas e uma alça remendada com arame.","flag":false},{"vague":"estragado","options":["lascado","enferrujado","desgastado"],"weak":"A tigela está estragada.","strong":"A tigela está lascada na borda e o esmalte, desgastado no fundo.","flag":true},{"vague":"feito à mão","options":["artesanal","ornamental","utilitário"],"weak":"As peças são feitas à mão.","strong":"As peças parecem artesanais, segundo o vendedor; algumas são ornamentais e outras, utilitárias.","flag":false}]},{"scene":"Uma chaleira, uma lanterna de papel e uma bicicleta estacionada","focus":"Nomear as partes de um objeto substitui “aquela coisa” por precisão. Use o nome técnico só quando ele ajuda o público a visualizar.","terms":[["alça","Parte curva, geralmente lateral ou superior, feita para segurar ou carregar.","A alça de bambu da chaleira forma um arco sobre a tampa.","Diferencie alça (segurar com a mão em arco) de cabo (empunhar como haste)."],["cabo","Parte alongada por onde se segura um utensílio ou ferramenta.","O cabo de madeira da frigideira escureceu perto do encaixe.","Não chame de cabo uma alça em arco; observe como a mão segura."],["tampa","Peça que fecha a abertura de um recipiente.","A tampa de metal tem um pequeno furo por onde sai o vapor.","Diga se a tampa encaixa, rosqueia ou apenas repousa sobre a abertura."],["base","Parte inferior que sustenta o objeto.","A base larga da lanterna impede que ela tombe com o vento.","Base é a parte de apoio; não a confunda com o fundo interno de um recipiente."],["haste","Peça fina e longa que sustenta ou liga outras partes.","Uma haste de bambu prende a lanterna de papel ao beiral.","Use haste para peças finas; partes largas pedem outro termo, como coluna ou suporte."],["bojo","Parte arredondada e mais larga de um recipiente ou objeto.","O bojo da chaleira reflete as luzes da rua.","Bojo é a parte abaulada; não serve para objetos totalmente retos."],["encaixe","Ponto em que duas peças se unem por ajuste de formas.","No encaixe entre o cabo e a lâmina, a madeira está mais clara.","Descreva o tipo de união (encaixe, parafuso, solda, cola) só se for visível."],["dobradiça","Peça articulada que permite abrir e fechar portas, tampas ou abas.","A dobradiça da caixa range quando a vendedora a abre.","Não confunda dobradiça com encaixe fixo: a dobradiça permite giro."],["empilhável","Projetado para ser colocado um sobre o outro sem cair.","Cadeiras empilháveis formam uma torre colorida no canto do restaurante.","Empilhar objetos não os torna empilháveis por projeto; observe se há encaixe próprio."],["cilíndrico","Com forma de cilindro: corpo reto e seção circular.","A lanterna cilíndrica de papel vermelho tem franjas douradas na base.","Cilíndrico exige lados paralelos; formas que se estreitam são cônicas."]],"model":["Na calçada, há uma chaleira de metal, uma lanterna vermelha pendurada e uma bicicleta estacionada.","A chaleira tem bojo arredondado, tampa com furo de vapor e uma alça de bambu em arco.","Diferente da chaleira, a lanterna é cilíndrica e leve, presa ao beiral por uma haste fina de bambu.","Minha impressão é que os três objetos resolvem o mesmo problema de formas distintas: como ser segurado, pendurado ou apoiado."],"swaps":[{"vague":"negócio","options":["alça","haste","encaixe"],"weak":"Tem um negócio em cima da chaleira.","strong":"Há uma alça de bambu em arco sobre a chaleira, presa por dois encaixes de metal.","flag":false},{"vague":"redondo","options":["cilíndrico","bojo","base"],"weak":"A lanterna é redonda.","strong":"A lanterna é cilíndrica, com bojo levemente abaulado no meio e base franjada.","flag":false},{"vague":"pecinha","options":["dobradiça","tampa","encaixe"],"weak":"A caixa abre por uma pecinha.","strong":"A caixa abre por uma dobradiça de latão, e a tampa se fecha por encaixe.","flag":true}]},{"scene":"Um gato deitado na janela de uma casa antiga","focus":"Descreva pelagem, cores e partes do corpo com precisão. Raça, idade e saúde de um animal raramente podem ser afirmadas só pela aparência.","terms":[["pelagem","Conjunto dos pelos que cobrem o corpo de um animal.","A pelagem curta e cinzenta do gato brilha onde o sol bate.","Não deduza raça pela pelagem; muitas cores aparecem em animais sem raça definida."],["plumagem","Conjunto das penas de uma ave.","A plumagem do pombo muda de verde para roxo no pescoço conforme a luz.","Cores de plumagem variam com a luz e a estação; descreva o que viu naquele momento."],["malhado","Com manchas de cores diferentes distribuídas pelo corpo.","Um cachorro malhado de preto e branco dorme sob o banco.","Diga as cores e onde ficam as manchas, em vez de apenas “malhado”."],["rajado","Com listras ou faixas de cor no pelo.","O gato rajado tem listras escuras que descem da espinha para a barriga.","Rajado (listras) é diferente de malhado (manchas)."],["focinho","Parte da frente da cabeça de um animal, onde ficam o nariz e a boca.","O focinho úmido do cachorro encosta na grade do portão.","Focinho úmido ou seco não serve como diagnóstico de saúde."],["cauda","Prolongamento posterior do corpo de muitos animais; o mesmo que rabo.","A cauda do gato pende da janela e se move devagar.","Movimentos da cauda variam entre espécies; não os traduza diretamente em emoção."],["porte","Tamanho e estrutura geral de um animal.","Um cão de pequeno porte acompanha o passo da dona.","Use porte para tamanho; ele não indica idade nem raça."],["bico","Estrutura dura e alongada da boca das aves.","Com o bico curto, o pardal recolhe migalhas entre as pedras.","Formato do bico ajuda a distinguir aves, mas identificação de espécie exige fonte."],["patas","Membros de apoio e locomoção dos animais.","As patas brancas do gato contrastam com o pelo escuro do corpo.","Diferencie patas dianteiras e traseiras quando a posição importar para a cena."],["escamoso","Coberto por escamas, placas pequenas e sobrepostas.","O peixe escamoso reflete a luz no balde de água do mercado.","Escamas indicam grupo de animal, não frescor ou qualidade do alimento."]],"model":["Na janela de uma casa antiga, um gato está deitado sobre o parapeito de madeira.","Ele é rajado, com pelagem cinzenta e listras escuras, e as patas dianteiras brancas pendem para fora.","Ao contrário dos pombos na calçada, cuja plumagem muda de cor com a luz, o gato quase não se move.","Para mim, o gato parece parte da fachada — uma impressão minha, já que não sei se ele vive ali."],"swaps":[{"vague":"fofo","options":["pelagem","porte","patas"],"weak":"Era um cachorro fofo.","strong":"Era um cachorro de pequeno porte, de pelagem longa e clara, com patas curtas.","flag":true},{"vague":"pintado","options":["malhado","rajado","plumagem"],"weak":"O gato é pintado.","strong":"O gato é rajado, com listras escuras sobre o fundo cinza; o vizinho é malhado de branco.","flag":true},{"vague":"bicho","options":["porte","pelagem","cauda"],"weak":"Tinha um bicho na janela.","strong":"Havia um gato de porte médio na janela, de pelagem escura e cauda longa.","flag":true}]},{"scene":"Pombos e um cachorro numa praça ao amanhecer","focus":"Descreva ações observáveis. Evite atribuir pensamentos e sentimentos humanos aos animais — o antropomorfismo pode ser charmoso, mas não é informação.","terms":[["ciscar","Revolver o chão com as patas ou o bico em busca de alimento.","Os pombos ciscam entre as pedras perto da lixeira.","Ciscar é ação de aves; não o use para outros animais."],["empoleirado","Pousado em ponto elevado, como galho, fio ou beiral.","Um pardal empoleirado no fio observa o movimento da calçada.","Diga onde a ave está pousada e por quanto tempo."],["à espreita","Observando com atenção e imóvel, como antes de uma ação.","O gato permanece à espreita atrás do vaso, com os olhos nos pombos.","A postura sugere atenção; não afirme o que o animal pretende fazer."],["arisco","Que se afasta rapidamente quando alguém se aproxima.","Arisco, o gato some sob o carro quando a criança chega perto.","Evite associar o comportamento a maus-tratos sem evidência."],["dócil","Que aceita a aproximação ou o toque sem se afastar.","Dócil, o cachorro deixa a criança acariciar sua cabeça.","Comportamento dócil num momento não garante segurança; não incentive aproximar-se de animais desconhecidos."],["enrodilhado","Deitado com o corpo curvado em círculo.","Enrodilhado sobre o capô ainda morno, o gato dorme.","Descreva a posição; frio ou conforto são hipóteses."],["saltitante","Que se desloca com pequenos saltos.","Saltitante, o pardal avança entre as mesas do café.","Use para o modo de deslocamento, não para o humor do animal."],["em bando","Em grupo, movendo-se ou permanecendo juntos.","Em bando, os pombos levantam voo quando o ônibus passa.","Bando é termo usual para aves; para outros animais, prefira grupo, matilha ou cardume."],["farejar","Cheirar repetidamente para examinar algo.","O cachorro fareja cada poste antes de seguir o passeio.","Farejar é ação observável; o que o animal identificou é suposição."],["alerta","Com a cabeça erguida e atenção voltada para um estímulo.","Com as orelhas erguidas, o cão fica alerta ao som da bicicleta.","Diga o estímulo que provocou a reação, se ele for visível ou audível."]],"model":["Na praça, ao amanhecer, um bando de pombos cisca perto da lixeira e um cachorro fareja os canteiros.","Um pardal empoleirado no fio observa o movimento, enquanto um gato permanece à espreita atrás de um vaso.","Quando um ônibus passa, os pombos levantam voo em bando; o cachorro, alerta, apenas ergue as orelhas.","Minha impressão é que cada animal ocupa a praça num ritmo próprio — impressão de observador, não leitura do que eles sentem."],"swaps":[{"vague":"medroso","options":["arisco","alerta","à espreita"],"weak":"O gato é medroso.","strong":"O gato é arisco: afastou-se para baixo do carro e ficou alerta até a criança ir embora.","flag":false},{"vague":"bonzinho","options":["dócil","farejar","alerta"],"weak":"O cachorro é bonzinho.","strong":"O cachorro foi dócil: deixou a criança se aproximar depois de farejar sua mão.","flag":true},{"vague":"brincando","options":["saltitante","ciscar","em bando"],"weak":"Os passarinhos estavam brincando.","strong":"Os pardais estavam saltitantes entre as mesas, ciscando migalhas em bando.","flag":false}]},{"scene":"A vista do alto de um mirante sobre o rio","focus":"Uma vista ampla precisa de ordem: do primeiro plano ao horizonte. Distâncias estimadas a olho devem ser apresentadas como estimativas.","terms":[["horizonte","Linha onde o céu parece encontrar a terra ou a água.","No horizonte, as torres se dissolvem na névoa da tarde.","A visibilidade do horizonte depende do clima; registre as condições."],["skyline","Contorno dos edifícios de uma cidade recortado contra o céu.","O skyline de Lujiazui forma uma linha irregular de torres do outro lado do rio.","Termo em inglês consagrado; em português, “perfil urbano” ou “silhueta da cidade” também servem."],["mirante","Lugar elevado de onde se observa uma vista ampla.","Do mirante, o rio aparece como uma faixa cinza entre as duas margens.","Diga como se chega ao mirante e se ele é público, caso o público possa querer ir."],["panorama","Vista ampla de uma paisagem ou cidade em várias direções.","O panorama abrange a curva do rio, as pontes e os bairros baixos ao sul.","Um panorama não é visto por inteiro de uma vez; diga a direção do olhar."],["vista aérea","Visão de cima para baixo, como a partir de um ponto muito alto ou de um drone.","Na vista aérea, os pátios dos lilongs formam retângulos regulares.","Imagens de drone exigem verificação de regras locais e indicação de origem."],["ponto de fuga","Ponto em que linhas paralelas parecem se encontrar na distância.","Os trilhos convergem para um ponto de fuga sob a ponte.","É efeito de perspectiva, não característica real do espaço."],["à distância","Afastado do observador; longe.","À distância, um navio cargueiro avança devagar rio acima.","Estimativas de distância a olho são imprecisas; indique como chegou ao número."],["emoldurado","Visto através de algo que o envolve como moldura, como janela, arco ou galhos.","O pagode aparece emoldurado pelos galhos dos salgueiros.","A moldura é escolha de enquadramento; diga quando você escolheu o ângulo."],["desobstruído","Sem barreiras que impeçam a visão.","Do último andar, a vista do rio é desobstruída em toda a extensão.","Vista desobstruída num ponto não vale para o local inteiro."],["recortado","Com contorno nítido destacado contra um fundo.","As antenas das torres aparecem recortadas contra o céu laranja.","O efeito depende da luz; à noite ou com névoa, o contorno muda."]],"model":["Do mirante, vejo o rio em curva, duas pontes e, à distância, um conjunto de torres.","Em primeiro plano estão os telhados baixos; ao fundo, o skyline aparece recortado contra o céu da tarde.","Enquanto a margem próxima é horizontal e densa, a margem oposta sobe em torres que dominam o horizonte.","Minha impressão é que o rio separa duas escalas de cidade — leitura pessoal de quem a observa de um único ponto."],"swaps":[{"vague":"vista linda","options":["panorama","desobstruído","horizonte"],"weak":"Que vista linda!","strong":"Do mirante, o panorama é desobstruído até o horizonte, onde o rio faz uma curva.","flag":true},{"vague":"lá longe","options":["à distância","horizonte","ponto de fuga"],"weak":"Lá longe tem uns prédios.","strong":"À distância, perto do horizonte, há um conjunto de torres.","flag":true},{"vague":"dá pra ver tudo","options":["panorama","vista aérea","mirante"],"weak":"Lá de cima dá pra ver tudo.","strong":"Do mirante, o panorama abrange o rio, as pontes e os bairros ao sul, quase como uma vista aérea.","flag":true}]},{"scene":"Um parque com lago, ponte de pedra e colinas ao longe","focus":"Nomeie relevo, água e vegetação com precisão geográfica simples. Em parques urbanos, diferencie o que é natural do que foi construído ou plantado.","terms":[["relevo","Conjunto das formas do terreno: elevações, depressões e planos.","O relevo do parque é suave, com pequenas elevações ao redor do lago.","Parques urbanos podem ter relevo artificial; pesquise antes de chamá-lo de natural."],["colina","Elevação de terreno arredondada e de pouca altura.","Uma colina coberta de bambus fecha a vista ao norte.","Colina é menor e mais suave que um morro ou montanha."],["planície","Extensão de terreno plano ou quase plano.","Além do parque, a planície se estende até as primeiras torres.","Diga o que ocupa a planície: campo, cidade, cultivo."],["margem","Faixa de terra ao longo de um rio, lago ou canal.","Na margem do lago, salgueiros inclinam os galhos sobre a água.","Margem é a terra junto à água; a própria água junto à terra é a beira ou a orla."],["vegetação rasteira","Plantas baixas que cobrem o solo, como grama e arbustos pequenos.","Vegetação rasteira cobre as encostas entre as pedras.","Diferencie vegetação rasteira de canteiros plantados com espécies ornamentais."],["copa","Parte superior de uma árvore, formada por galhos e folhas.","As copas largas dos plátanos se encontram sobre a alameda.","Identificar a espécie da árvore exige fonte ou placa; descreva a forma se não souber."],["bosque","Área de árvores próximas, menor que uma floresta.","Um pequeno bosque de pinheiros abafa o barulho da avenida.","Em parques, o bosque costuma ser plantado; diga se não for possível saber."],["espelho d'água","Superfície de água parada que reflete o entorno.","O espelho d'água reflete o pavilhão vermelho quase sem distorção.","O reflexo depende de vento e luz; no dia seguinte a superfície pode estar agitada."],["curso d'água","Água que corre por um leito, como rio, riacho ou canal.","Um curso d'água estreito liga o lago a um canal mais antigo.","Diferencie rio, riacho e canal; canais são geralmente construídos."],["ribeirinho","Situado à beira de um rio ou que vive junto a ele.","Casas ribeirinhas de dois andares acompanham a curva do canal.","Ao falar de comunidades ribeirinhas, evite romantizar ou generalizar modos de vida."]],"model":["No parque, um lago ocupa o centro, atravessado por uma ponte de pedra em arco.","Na margem, salgueiros inclinam as copas sobre o espelho d'água, e uma colina de bambus fecha a vista ao norte.","Diferentemente da margem sul, plana e gramada, a margem norte sobe em relevo suave coberto de vegetação rasteira.","Para mim, o parque imita uma paisagem natural — mas, como em muitos jardins urbanos, boa parte dela provavelmente foi desenhada."],"swaps":[{"vague":"natureza","options":["bosque","vegetação rasteira","copa"],"weak":"O parque tem muita natureza.","strong":"O parque tem um bosque de pinheiros, vegetação rasteira nas encostas e copas largas sobre a alameda.","flag":false},{"vague":"laguinho","options":["espelho d'água","margem","curso d'água"],"weak":"Tem um laguinho no meio.","strong":"No centro, há um espelho d'água com margens de pedra, ligado a um curso d'água estreito.","flag":true},{"vague":"morrinho","options":["colina","relevo","planície"],"weak":"Tem um morrinho no fundo.","strong":"Ao fundo, uma colina baixa quebra o relevo plano da planície ao redor.","flag":true}]},{"scene":"Uma avenida minutos antes de uma chuva de verão","focus":"Clima muda em minutos: indique a hora e o lugar. Diferencie o que você observa (nuvens, vento) de dados meteorológicos, que exigem fonte.","terms":[["encoberto","Com o céu totalmente coberto de nuvens.","Com o céu encoberto, as fachadas de vidro perdem os reflexos.","Diferencie encoberto (totalmente) de nublado com abertas."],["límpido","Claro, sem nuvens nem névoa.","Depois da chuva, o céu límpido deixa ver as colinas a oeste.","Céu límpido não significa ar limpo; qualidade do ar exige dado oficial."],["neblina","Névoa próxima do chão que reduz a visibilidade.","A neblina apaga o topo das torres às sete da manhã.","Não confunda neblina com poluição; sem medição, descreva apenas a visibilidade."],["garoa","Chuva muito fina e contínua.","Uma garoa fina deixa a calçada brilhante sem formar poças.","Garoa é diferente de chuvisco intermitente; observe a continuidade."],["aguaceiro","Chuva forte e repentina, geralmente de curta duração.","Um aguaceiro de dez minutos alaga a faixa de pedestres.","Informe a duração observada; “tempestade” exige mais que chuva forte."],["mormaço","Calor abafado com céu nublado ou sol fraco.","No mormaço da tarde, os vendedores se abrigam sob os toldos.","Mormaço é sensação local; temperatura exata exige fonte."],["abafado","Quente, úmido e com pouca circulação de ar.","O ar abafado da estação faz as pessoas abanarem os rostos com leques.","Diga se é sensação sua ou dado medido."],["crepúsculo","Período de luz difusa logo após o pôr do sol ou antes do nascer.","No crepúsculo, as luzes do rio acendem enquanto o céu ainda está azul.","Crepúsculo é intervalo de tempo; indique o horário aproximado."],["rajada","Golpe de vento forte e passageiro.","Uma rajada vira os guarda-chuvas na esquina e espalha folhas.","Rajada é vento momentâneo, diferente de ventania contínua."],["orvalho","Gotículas de água que se formam em superfícies frias durante a noite.","O orvalho ainda cobre os bancos do parque às seis da manhã.","Orvalho não é sinal de chuva noturna; observe se o chão está seco."]],"model":["Às cinco da tarde, o céu sobre a avenida está encoberto, e o ar parece parado.","No mormaço, os vendedores puxam os toldos; uma rajada levanta poeira e folhas pela calçada.","Minutos depois, a garoa fina dá lugar a um aguaceiro, e a avenida, antes abafada, se esvazia rapidamente.","Minha impressão é que a chuva reorganiza a rua em segundos — impressão de um único fim de tarde, não um padrão da cidade."],"swaps":[{"vague":"feio","options":["encoberto","neblina","aguaceiro"],"weak":"O tempo está feio.","strong":"O céu está encoberto, com neblina sobre o rio e risco de aguaceiro no fim da tarde, segundo a previsão.","flag":true},{"vague":"quente","options":["abafado","mormaço","encoberto"],"weak":"Está muito quente.","strong":"O ar está abafado, num mormaço sem vento — a temperatura exata eu não medi.","flag":false},{"vague":"chuvinha","options":["garoa","aguaceiro","neblina"],"weak":"Caiu uma chuvinha.","strong":"Caiu uma garoa fina por meia hora, sem formar poças.","flag":true}]}];
